	public boolean isClassAndDoesNotHaveFlags(JavacNode typeNode, long flags) {
		this.utilityTypeNode = typeNode;
		typeNode = this.utilityTypeNode;
		JCClassDecl typeDecl = null;
		if (typeNode.get() instanceof JCClassDecl) typeDecl = (JCClassDecl) typeNode.get();
		else return false;

		long typeDeclflags = typeDecl == null ? 0 : typeDecl.mods.flags;
		return (typeDeclflags & flags) == 0;
	}

	public boolean isStaticAllowed(JavacNode typeNode) {
		this.utilityTypeNode = typeNode;
